import{_ as t}from"./chunks/calendar-view.D4HRaDVT.js";import{_ as a}from"./chunks/calendar-reschedule.DOz6rwXw.js";import{_ as o,H as r,f as s,i as n}from"./chunks/framework.CSxcEb-0.js";const f=JSON.parse('{"title":"Calendar","description":"","frontmatter":{},"headers":[],"relativePath":"guide/calendar.md","filePath":"guide/calendar.md"}'),l={name:"guide/calendar.md"};function i(c,e,d,g,h,u){return r(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="calendar" tabindex="-1">Calendar <a class="header-anchor" href="#calendar" aria-label="Permalink to &quot;Calendar&quot;">​</a></h1><p>The <strong>Calendar</strong> view is your planning surface: week, day, or month layout with drag-and-drop scheduling.</p><p><img src="'+t+'" alt="Calendar view"></p><h2 id="views" tabindex="-1">Views <a class="header-anchor" href="#views" aria-label="Permalink to &quot;Views&quot;">​</a></h2><p>Switch view mode from the calendar toolbar or Settings:</p><ul><li><strong>Week</strong> — primary scheduling view; tasks appear as blocks in time slots</li><li><strong>Day</strong> — focus on a single day</li><li><strong>Month</strong> — overview; useful for spotting density and navigating dates</li></ul><h2 id="reschedule" tabindex="-1">Reschedule <a class="header-anchor" href="#reschedule" aria-label="Permalink to &quot;Reschedule&quot;">​</a></h2><p>Press <strong>Recalculate schedule</strong> (toolbar refresh icon) to re-run the auto-scheduler for incomplete auto-scheduled tasks. <strong>Locked</strong> placements (from <strong>Lock in</strong> on drag or assigning a task to a slot) stay put; other tasks reflow around them.</p><p><strong>Unlock</strong> a locked block by clicking the <strong>open-lock</strong> icon on the calendar block, or uncheck <strong>Lock placement on calendar</strong> in the task editor. The block stays at its current time until you reschedule; then the scheduler can move it again. <strong>Postpone</strong> also clears the lock but pushes the earliest start time forward and clears manual placement.</p><p><strong>Auto-reschedule</strong> (Settings → Scheduler) runs the same engine after edits, optionally after a delay so rapid changes batch into one pass. Turn it off to edit freely and press <strong>Reschedule</strong> once when you are ready.</p><p>Run <strong>Reschedule</strong> manually after you change tasks, events, scheduling hours, or import data whenever auto-reschedule is off.</p><p><img src="'+a+'" alt="Recalculating the schedule"></p><h2 id="how-blocks-are-placed" tabindex="-1">How blocks are placed <a class="header-anchor" href="#how-blocks-are-placed" aria-label="Permalink to &quot;How blocks are placed&quot;">​</a></h2><ol><li>Tasks are ordered by <strong>priority</strong>, then <strong>due date</strong></li><li><strong>Dependencies</strong> are respected (a task cannot start before its predecessors finish)</li><li>Free slots are found inside the task’s <strong>scheduling hours</strong> profile, avoiding <strong>busy events</strong> and other scheduled items</li><li><strong>Splittable</strong> tasks can use multiple smaller blocks; non-splittable tasks need one contiguous slot</li></ol><h2 id="deleting-recurring-items" tabindex="-1">Deleting recurring items <a class="header-anchor" href="#deleting-recurring-items" aria-label="Permalink to &quot;Deleting recurring items&quot;">​</a></h2><p>When you delete a <strong>repeating event</strong>, <strong>repeating task</strong>, or <strong>routine</strong> from the calendar (click the block, then <strong>Delete</strong>), TemPad asks:</p><ul><li><strong>This occurrence only</strong> — hides that date; the series continues</li><li><strong>This and following</strong> — ends the series before that date</li><li><strong>All occurrences</strong> — removes the entire series</li></ul><p>If you open the editor from a list without picking a calendar block, you can still delete <strong>all occurrences</strong>; use the calendar to target a specific date for the other options.</p><p>Imported <strong>Google Calendar</strong> recurring events sync deletes back to Google when you have write access to that calendar.</p><h2 id="drag-and-lock" tabindex="-1">Drag and lock <a class="header-anchor" href="#drag-and-lock" aria-label="Permalink to &quot;Drag and lock&quot;">​</a></h2><ul><li><strong>Click</strong> a block to edit it</li><li><strong>Drag</strong> to move a task or event to a new time</li><li>Dragged task blocks become <strong>locked</strong> (dashed outline) until the next <strong>Reschedule</strong></li><li>Overlapping blocks in the same hour are shown side-by-side</li></ul><h2 id="google-calendar-busy-blocks" tabindex="-1">Google Calendar busy blocks <a class="header-anchor" href="#google-calendar-busy-blocks" aria-label="Permalink to &quot;Google Calendar busy blocks&quot;">​</a></h2><p>Imported Google events appear as busy constraints. TemPad auto-syncs while the tab is open (and when you return). Use <strong>Sync now</strong> in Settings for an immediate pull.</p><p>Optional <strong>travel / decompress</strong> child blocks can sit before or after busy events (not free events). See <a href="./google-calendar#travel-decompress-buffers-optional">Google Calendar — Travel / decompress buffers</a>.</p><p>See <a href="./google-calendar">Google Calendar</a> for connect and two-way sync details.</p>',25)])])}const b=o(l,[["render",i]]);export{f as __pageData,b as default};
